109	        // iterate the form control elements and accumulate their values
110	        Elements formEls = elements();
111	        for (Element el: formEls) {
112	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
113	            if (isDisabled(el)) continue; // skip disabled form inputs
